import 'package:flutter_test/flutter_test.dart';import 'package:surge_wizard/core/combat_board_v4.dart';import 'package:surge_wizard/core/combat_state_v4.dart';import 'package:surge_wizard/core/hex_coord_v4.dart';import 'package:surge_wizard/core/spell_catalog_v4.dart';import 'package:surge_wizard/core/target_resolver_v4.dart';CombatUnitV4 caster()=>CombatUnitV4(id:'w',name:'w',team:CombatTeamV4.party,anchor:const HexCoord(1,3),stats:const UnitStatsV4(maxHp:60,speed:100,move:2,evasion:11,fortitude:11,resolve:11,brace:11));void main(){const r=TargetResolverV4();final b=CombatBoardV4();test('Burst7 has seven cells away from border',(){expect(r.resolveHexes(spell:SpellCatalogV4.fireball,caster:caster(),target:const HexCoord(4,3),board:b).length,7);});test('line stays in board',(){final c=r.resolveHexes(spell:SpellCatalogV4.iceLance,caster:caster(),target:const HexCoord(6,3),board:b);expect(c.every(b.valid),isTrue);});}
